@contextlib.contextmanager
def temp_root():
    """把「库根」临时指向一个合成目录，**只在本进程内**改模块级变量。

    为什么要它：selftest 必须走真实的写盘路径（否则测的是另一个函数），
    但**绝对不能在真库上写**。做法是让 ROOT 在 selftest 期间整体指向 tempfile
    合成库——写盘路径一字不改地跑，落点全在临时目录里。退出时无论成败都恢复。
    """
    old_root, old_cwd = ROOT, os.getcwd()
    tmp = K.make_temp_dir(prefix="qc_fix_authors_selftest_")
    try:
        globals()["ROOT"] = tmp
        os.chdir(tmp)
        yield tmp
    finally:
        os.chdir(old_cwd)
        globals()["ROOT"] = old_root
        shutil.rmtree(tmp, ignore_errors=True)



def parse_authors(v):
    """把字符串解析成姓名列表；无法可靠解析时返回 None。"""
    if not isinstance(v, str):
        return None
    s = v.strip()
    if PROSE.search(s):
        return None  # 散文式，需人工处理
    # 形态 2/3：开头的 "- " 是 YAML 列表标记被误写进字符串；先剥掉
    s = re.sub(r"^\s*-\s+", "", s)
    # 形态 1：JSON 数组 / 括号人名串
    if s.startswith("[") and s.endswith("]"):
        body = s[1:-1]
        # 可能带引号（["A","B"]）也可能不带（[A, B, C]）
        if '"' in body:
            parts = re.split(r'",\s*"', body)
            parts = [p.strip().strip('"').strip("'") for p in parts]
        else:
            parts = [p.strip() for p in body.split(",")]
        parts = [p for p in parts if p]
        return parts or None
    # 形态 2：Markdown 破折号列表  "- A - B - C"
    if " - " in s and "," not in s:
        parts = [p.strip() for p in s.split(" - ") if p.strip()]
        if len(parts) > 1:
            return parts
    # 形态 3：逗号分隔。⚠️ 含「姓, 名首字母」写法（`Li H., Hao J.`），
    # 不能用逗号直接切 —— 需识别 `Xxx Y.,` 模式
    if "." in s and "," in s:
        # 用「句点+逗号/空格」作为分隔，保住 `Qiao S.-Z.` 这类
        parts = re.split(r"(?<=\.)\s*,\s*", s)
        parts = [p.strip() for p in parts if p.strip()]
        if len(parts) > 1:
            return parts
    if "," in s:
        parts = [p.strip() for p in s.split(",") if p.strip()]
        if len(parts) > 1:
            return parts
    return [s] if s else None


def rewrite_authors(t, names):
    """把页面里的标量 authors 改写成 YAML 列表，返回新全文。

    ⚠️ 2026-10-05 修复：原实现用 `t[i + 4:]` 取正文。对**标题行式**
    frontmatter（`---\ntitle: x`）算出的 `i = t.find("\\n---", 3)` 会**包含**
    闭合标记前的换行 ⇒ `i + 4` 把该换行一起吃掉，**每个被改写的文件都丢一个换行**
    （可能让正文首行与 `---` 粘连）。改用 `split_frontmatter` 同一解析器切分。
    """
    fm_text, body = split_frontmatter(t)
    # ⚠️ 判据修正：`split_frontmatter` 无 frontmatter 时返回 `("", text)`，
    #    **永远不是 None**。旧写法 `if fm_text is None` 是死条件，等于这道
    #    「没有 frontmatter 就不许乱写」的闸门从来没关上过。
    if not fm_text.strip():
        return None
    lines = fm_text.split("\n")
    out, skipping = [], False
    for ln in lines:
        if re.match(r"^authors\s*:", ln):
            out.append("authors:")
            for n in names:
                out.append('  - "%s"' % n.replace('"', '\\"'))
            skipping = True
            continue
        if skipping:
            # 吃掉原 authors 的续行（列表项或其缩进延续）
            if re.match(r"^\s+-\s", ln) or re.match(r"^\s+", ln):
                continue
            skipping = False
        out.append(ln)
    newhead = "\n".join(out)
    # 写前复核：必须能被同一解析器读出，且 authors 确为 list
    from kb_lib import join_frontmatter
    new_text = join_frontmatter(newhead, body)
    chk, _ = split_frontmatter(new_text)
    if not chk.strip():
        return None
    try:
        fm2 = yaml.safe_load(chk)
    except Exception:
        return None
    if not isinstance(fm2, dict) or not isinstance(fm2.get("authors"), list):
        return None
    return new_text


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）+ 写盘路径隔离夹具。"""
    ok = True

    # 🔴 守卫：进入时对真实落点拍快照，退出前比对——证明自检没碰真实库
    guard = _guard_state(wiki_glob=True, extra_paths=(os.path.join(ROOT, ".qc"),))

    # ---- 形态解析夹具 ----
    cases = [
        ('["A", "B"]', ["A", "B"], "JSON 数组带引号"),
        ("[A, B, C]", ["A", "B", "C"], "括号无引号"),
        ("- A - B - C", ["A", "B", "C"], "Markdown 破折号串"),
        ("Li H., Hao J., Qiao S.-Z.", ["Li H.", "Hao J.", "Qiao S.-Z."],
         "姓+名首字母（勿按逗号硬切）"),
    ]
    for src, want, label in cases:
        got = parse_authors(src)
        print(f"  [{'ok' if got == want else 'FAIL'}] 正例 {label} -> {got}")
        ok = ok and got == want

    # 反例：散文式必须返回 None（不得自动改）
    got = parse_authors("（多作者，Acceleration Consortium / 多伦多大学等）")
    print(f"  [{'ok' if got is None else 'FAIL'}] 反例 散文式返回 None（仅报告）")
    ok = ok and got is None

    # 反例：非字符串输入返回 None
    got = parse_authors(["A", "B"])
    print(f"  [{'ok' if got is None else 'FAIL'}] 反例 非字符串输入 -> None")
    ok = ok and got is None

    # 🔴 回归夹具：改写**不得丢换行**（原实现对标题行式 frontmatter 会丢一个）
    t = ("---\n"
         "created: 2026-01-01\n"
         'authors: "Li H., Hao J."\n'
         "type: source\n"
         "---\n"
         "# 标题\n"
         "正文首行\n")
    new = rewrite_authors(t, ["Li H.", "Hao J."])
    good = new is not None
    if good:
        fm, body = split_frontmatter(new)
        good = (fm is not None
                and body.startswith("# 标题")
                and "\n# 标题" in new
                and isinstance(yaml.safe_load(fm).get("authors"), list))
    print(f"  [{'ok' if good else 'FAIL'}] 🔴 回归：改写后不丢换行、正文首行完整")
    ok = ok and good

    # 正例：改写结果 authors 必须是 list 且值正确
    if new:
        fm, _ = split_frontmatter(new)
        got = yaml.safe_load(fm).get("authors")
        want = ["Li H.", "Hao J."]
        print(f"  [{'ok' if got == want else 'FAIL'}] 正例 改写结果 -> {got}")
        ok = ok and got == want

    # 反例：没有 frontmatter 的文本返回 None（不得乱写）
    got = rewrite_authors("# 没有 frontmatter\n", ["A"])
    print(f"  [{'ok' if got is None else 'FAIL'}] 反例 无 frontmatter -> None")
    ok = ok and got is None

    # ---- 夹具（只对合成库，绝不碰真库）：完整写盘路径 ----
    try:
        with temp_root() as tmp:
            wd = os.path.join(tmp, "wiki", "sources")
            os.makedirs(wd, exist_ok=True)
            p1 = os.path.join(wd, "A-标量authors.md")
            p2 = os.path.join(wd, "B-正常.md")
            with open(p1, "w", encoding="utf-8", newline="\n") as fh:
                fh.write("---\ncreated: 2026-01-01\n"
                         'authors: "Li H., Hao J."\n'
                         "type: source\n---\n\n# 标题\n正文首行\n")
            with open(p2, "w", encoding="utf-8", newline="\n") as fh:
                fh.write('---\nauthors: ["A", "B"]\n---\n\n# 好页\n')

            # 夹具 1（正例）：只挑出标量 authors 的那一页
            todo, skipped = collect()
            c1 = ([os.path.basename(x[0]) for x in todo] == ["A-标量authors.md"]
                  and not skipped)
            print(f"  [{'ok' if c1 else 'FAIL'}] 夹具 正例 合成库只标出标量 authors 页 -> "
                  f"{[os.path.basename(x[0]) for x in todo]}")
            ok = ok and c1

            # 夹具 2（🔴 frontmatter 不丢）：走真实写盘路径：备份 → 写 → 写后复算
            saved = backup_files([x[0] for x in todo])
            written = []
            for f, page, old_a, names in todo:
                new_text = rewrite_authors(read_text(f), names)
                if new_text is None:
                    continue
                write_keep_eol(f, new_text)
                written.append(f)
            fm, body = split_frontmatter(read_text(p1))
            parsed = yaml.safe_load(fm)
            # ⚠️ `collect()` 与 `backup_files` 的路径写法不同（相对 vs 绝对），
            #    比较前统一 abspath，否则夹具会因为"路径写法"假失败。
            c2 = ([os.path.abspath(x) for x in written] == [os.path.abspath(p1)]
                  and len(saved) == 1
                  and isinstance(parsed, dict)
                  and parsed.get("authors") == ["Li H.", "Hao J."]
                  and body.lstrip().startswith("# 标题"))
            print(f"  [{'ok' if c2 else 'FAIL'}] 🔴 夹具 frontmatter 不丢：写后 authors 仍是 "
                  f"list 且正文首行完整（备份 {len(saved)} / 写 {len(written)}）")
            ok = ok and c2

            # 反例：写后复算必须抓出"写了但 frontmatter 读不出"的页（124 页事故形态）
            p_broken = os.path.join(wd, "C-写坏了.md")
            with open(p_broken, "w", encoding="utf-8", newline="\n") as fh:
                fh.write("---\nauthors: x\n---# 标题\n")
            caught = False
            sys.stdout.flush()          # 让下面 stderr 的告警落在夹具判定之后，输出不串行
            try:
                verify_written([p1, p_broken])
            except SystemExit as e:
                caught = (e.code or 0) != 0
            print(f"  [{'ok' if caught else 'FAIL'}] 反例 写后复算抓出 frontmatter 丢失"
                  f"（并置非零退出）")
            ok = ok and caught
    except Exception as e:                                        # noqa: BLE001
        print(f"  [FAIL] 夹具异常: {type(e).__name__}: {e}")
        ok = False

    # 🔴 守卫：自检未改动仓库内任何落点
    diff = _guard_diff(guard, _guard_state(
        wiki_glob=True, extra_paths=(os.path.join(ROOT, ".qc"),)))
    print(f"  [{'ok' if not diff else 'FAIL'}] 🔴 守卫：自检未改动仓库内任何落点"
          f"（{len(diff)} 处变化）")
    if diff:
        for d in diff[:10]:
            print("       ", d)
    ok = ok and not diff

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def collect():
    """返回 (todo, skipped)。"""
    todo, skipped = [], []
    for f in sorted(glob.glob("wiki/**/*.md", recursive=True)):
        if "/.index/" in f.replace(os.sep, "/"):
            continue
        t = read_text(f)
        # 🔴 改用与写盘复核**同一个**解析器切分：原先手写 `t.find("\n---", 3)` +
        #    `t[3:i]` 与 `kb_lib` 的规则不同（对 `---` 后的行尾/空白处理不一致），
        #    会出现"扫描用一套规则、写前复核用另一套"的错位——正是铁律 2 要杜绝的。
        fm_text, _body = split_frontmatter(t)
        if not fm_text.strip():
            continue
        try:
            fm = yaml.safe_load(fm_text)
        except Exception:
            continue
        if not isinstance(fm, dict):
            continue
        a = fm.get("authors")
        if not isinstance(a, str):
            continue
        names = parse_authors(a)
        if not names:
            skipped.append((os.path.basename(f)[:-3], a[:70]))
            continue
        todo.append((f, os.path.basename(f)[:-3], a, names))
    return todo, skipped


def main():
    ap = argparse.ArgumentParser(description="修复 authors 被写成纯字符串的 schema 缺陷")
    ap.add_argument("--apply", action="store_true", help="就地修复（默认干跑）")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    a = ap.parse_args()
    if a.selftest:
        return selftest()

    todo, skipped = collect()

    for f, page, old, names in todo:
        print("  ✅ %s" % page)
        print("       %s" % old[:70])
        print("    →  %s" % names)
    for page, old in skipped:
        print("  ⚠️ 跳过（散文式，需人工）: %s | %s" % (page, old))

    print("\n可自动修复 %d 页 ｜ 需人工 %d 页" % (len(todo), len(skipped)))
    if not a.apply:
        if todo:
            print("加 --apply 执行修复")
        return 0

    # —— 铁律 3：批量写盘前先备份、写后复算总量 ——
    saved = backup_files([x[0] for x in todo])
    if todo and not saved:
        print("❌ 备份失败，拒绝写盘", file=sys.stderr)
        return 2
    print("备份 %d 个待改文件 -> %s" % (len(saved), backup_dir()))

    written = []
    for f, page, old_a, names in todo:
        t = read_text(f)
        new_text = rewrite_authors(t, names)   # 内含「同一解析器」写前复核
        if new_text is None:
            print("  ❌ 失败（未写盘）: %s" % page)
            continue
        write_keep_eol(f, new_text)             # 保原换行风格，避免整篇 diff
        written.append(f)
    print("\n已修复 %d 页" % len(written))
    verify_written(written)
    return 0


if __name__ == "__main__":
    sys.exit(main())
